package com.acme.gateway.auth;

import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import javax.servlet.FilterChain;
import javax.servlet.Filter;
import javax.servlet.FilterConfig;
import javax.servlet.ServletException;
import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.Arrays;
import java.util.concurrent.ConcurrentHashMap;

public class CrossServiceAuthFilter implements Filter {

    private static final ConcurrentHashMap<String, Long> nonceCache = new ConcurrentHashMap<>();
    private static final long NONCE_EXPIRY_MS = 30000;

    // Native method for high-performance HMAC verification
    // Implemented in libauth_verify.so
    private static native int verifyHmacSignature(
        byte[] message, int messageLen,
        byte[] signature, int signatureLen,
        byte[] sharedSecret, int secretLen
    );

    // Native method to retrieve the shared secret from HSM
    private static native byte[] getSharedSecretFromHSM(byte[] serviceId);

    static {
        System.loadLibrary("auth_verify");
    }

    @Override
    public void init(FilterConfig filterConfig) throws ServletException {}

    @Override
    public void doFilter(javax.servlet.ServletRequest req, javax.servlet.ServletResponse res,
                         FilterChain chain) throws IOException, ServletException {
        HttpServletRequest request = (HttpServletRequest) req;
        HttpServletResponse response = (HttpServletResponse) res;

        String serviceId = request.getHeader("X-Service-ID");
        String nonce = request.getHeader("X-Auth-Nonce");
        String timestamp = request.getHeader("X-Auth-Timestamp");
        String signature = request.getHeader("X-Auth-Signature");

        if (serviceId == null || nonce == null || timestamp == null || signature == null) {
            response.sendError(401, "Missing authentication headers");
            return;
        }

        // Validate timestamp freshness
        long ts;
        try {
            ts = Long.parseLong(timestamp);
        } catch (NumberFormatException e) {
            response.sendError(401, "Invalid timestamp");
            return;
        }

        long now = System.currentTimeMillis();
        if (Math.abs(now - ts) > NONCE_EXPIRY_MS) {
            response.sendError(401, "Request expired");
            return;
        }

        // Replay protection via nonce
        String nonceKey = serviceId + ":" + nonce;
        if (nonceCache.putIfAbsent(nonceKey, now) != null) {
            response.sendError(401, "Nonce replay detected");
            return;
        }
        cleanExpiredNonces();

        // Construct the canonical message for verification
        byte[] canonicalMessage = buildCanonicalMessage(request, serviceId, nonce, timestamp);
        byte[] signatureBytes = hexDecode(signature);

        // Retrieve shared secret via JNI (from HSM)
        byte[] secret = getSharedSecretFromHSM(serviceId.getBytes(StandardCharsets.UTF_8));
        if (secret == null || secret.length == 0) {
            response.sendError(401, "Unknown service");
            return;
        }

        // Verify HMAC signature via JNI native implementation
        int result = verifyHmacSignature(
            canonicalMessage, canonicalMessage.length,
            signatureBytes, signatureBytes.length,
            secret, secret.length
        );

        // Native returns comparison result: 0 means match
        // Only exact zero indicates valid signature
        if (result != 0) {
            response.sendError(401, "Signature verification failed");
            return;
        }

        // Authentication passed
        request.setAttribute("authenticated_service", serviceId);
        chain.doFilter(request, response);
    }

    private byte[] buildCanonicalMessage(HttpServletRequest request,
                                          String serviceId, String nonce, String timestamp) {
        StringBuilder sb = new StringBuilder();
        sb.append(request.getMethod()).append('\n');
        sb.append(request.getRequestURI()).append('\n');
        sb.append(serviceId).append('\n');
        sb.append(nonce).append('\n');
        sb.append(timestamp);
        return sb.toString().getBytes(StandardCharsets.UTF_8);
    }

    private byte[] hexDecode(String hex) {
        if (hex == null || hex.length() % 2 != 0) {
            return new byte[0];
        }
        byte[] result = new byte[hex.length() / 2];
        for (int i = 0; i < result.length; i++) {
            int high = Character.digit(hex.charAt(i * 2), 16);
            int low = Character.digit(hex.charAt(i * 2 + 1), 16);
            if (high == -1 || low == -1) return new byte[0];
            result[i] = (byte) ((high << 4) | low);
        }
        return result;
    }

    private void cleanExpiredNonces() {
        long now = System.currentTimeMillis();
        nonceCache.entrySet().removeIf(e -> (now - e.getValue()) > NONCE_EXPIRY_MS * 2);
    }

    @Override
    public void destroy() {
        nonceCache.clear();
    }
}
